import pandas as pd, numpy as np, json

feats = pd.read_parquet("/tmp/test.parquet")
feats["as_of"] = pd.to_datetime(feats["as_of"], utc=True)
feats = feats.set_index(["customer_id", "as_of"])

rows = [json.loads(l) for l in open("/app/logs/live_2026-01_sample.jsonl")]
kept = ["orders_7d","orders_30d","spend_30d_cents","tickets_30d",
        "days_since_last_order","tenure_days","status","plan","app_minutes_7d","te_district"]

mism = {c:0 for c in kept}
total = 0
examples = {c:[] for c in kept}
for r in rows:
    cid = r["customer_id"]; asof = pd.Timestamp(r["as_of"], tz="UTC")
    total += 1
    if (cid, asof) not in feats.index:
        continue
    fr = feats.loc[(cid, asof)]
    for c in kept:
        exp = r["features"][c]
        got = fr[c]
        if isinstance(exp,(int,float)) and not isinstance(exp,bool):
            if pd.isna(got):
                ok = (exp is None)
            else:
                ok = abs(float(got)-float(exp)) <= 1e-6 + 1e-9*abs(float(exp))
        else:
            ok = (got == exp) if not (pd.isna(got) and exp is None) else True
        if not ok:
            mism[c]+=1
            if len(examples[c])<3:
                examples[c].append((cid, str(asof), exp, got))
print("total", total)
for c in kept:
    print(f"{c:22s} mismatches {mism[c]}")
for c in kept:
    if examples[c]:
        print("  ex", c, examples[c])
